package com.spotifycontroller;

import com.google.gson.Gson;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Consumer;
import javax.inject.Inject;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

final class LyricsClient
{
	private static final Logger log = LoggerFactory.getLogger(LyricsClient.class);
	private static final String API_URL = "https://lrclib.net/api/get";
	private static final long MAXIMUM_RESPONSE_BYTES = 1_048_576L;

	private final OkHttpClient httpClient;
	private final Gson gson;
	private final Object lock = new Object();
	private final Map<String, LyricsState> cache = new LinkedHashMap<String, LyricsState>(32, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<String, LyricsState> eldest)
		{
			return size() > 32;
		}
	};
	private final Map<String, List<Consumer<LyricsState>>> waiters = new HashMap<>();
	private long generation;

	@Inject
	LyricsClient(OkHttpClient httpClient, Gson gson)
	{
		this.httpClient = httpClient;
		this.gson = gson;
	}

	void requestLyrics(SpotifyPlaybackState state, Consumer<LyricsState> callback)
	{
		String key = keyFor(state);
		if (key.isEmpty())
		{
			callback.accept(LyricsState.empty());
			return;
		}

		long requestGeneration;
		synchronized (lock)
		{
			if (cache.containsKey(key))
			{
				callback.accept(cache.get(key));
				return;
			}
			List<Consumer<LyricsState>> existingWaiters = waiters.get(key);
			if (existingWaiters != null)
			{
				existingWaiters.add(callback);
				return;
			}
			List<Consumer<LyricsState>> newWaiters = new ArrayList<>();
			newWaiters.add(callback);
			waiters.put(key, newWaiters);
			requestGeneration = generation;
		}

		HttpUrl.Builder url = HttpUrl.parse(API_URL).newBuilder()
			.addQueryParameter("track_name", state.getTitle())
			.addQueryParameter("artist_name", state.getArtist());
		if (!state.getAlbum().trim().isEmpty())
		{
			url.addQueryParameter("album_name", state.getAlbum());
		}
		if (state.getDurationMs() > 0)
		{
			url.addQueryParameter("duration", Integer.toString(Math.max(1,
				Math.round(state.getDurationMs() / 1_000f))));
		}

		Request request = new Request.Builder()
			.url(url.build())
			.header("Accept", "application/json")
			.header("User-Agent", "RuneLite-Spotify-Controller/" + SpotifyControllerPlugin.PLUGIN_VERSION)
			.get()
			.build();
		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException exception)
			{
				log.debug("Lyrics request failed", exception);
				finish(key, LyricsState.empty(), false, requestGeneration);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response closeableResponse = response)
				{
					if (response.code() == 404)
					{
						finish(key, LyricsState.empty(), true, requestGeneration);
						return;
					}
					ResponseBody body = response.body();
					if (!response.isSuccessful() || body == null ||
						(body.contentLength() > MAXIMUM_RESPONSE_BYTES && body.contentLength() >= 0))
					{
						finish(key, LyricsState.empty(), false, requestGeneration);
						return;
					}
					String json = readBody(body);
					if (json == null)
					{
						finish(key, LyricsState.empty(), false, requestGeneration);
						return;
					}
					finish(key, LyricsParser.parse(json, gson), true, requestGeneration);
				}
				catch (IOException exception)
				{
					log.debug("Unable to read lyrics response", exception);
					finish(key, LyricsState.empty(), false, requestGeneration);
				}
			}
		});
	}

	private static String readBody(ResponseBody body) throws IOException
	{
		try (InputStream input = body.byteStream();
			ByteArrayOutputStream output = new ByteArrayOutputStream())
		{
			byte[] buffer = new byte[8_192];
			int total = 0;
			int read;
			while ((read = input.read(buffer)) != -1)
			{
				total += read;
				if (total > MAXIMUM_RESPONSE_BYTES)
				{
					return null;
				}
				output.write(buffer, 0, read);
			}
			return new String(output.toByteArray(), StandardCharsets.UTF_8);
		}
	}

	void reset()
	{
		synchronized (lock)
		{
			generation++;
			cache.clear();
			waiters.clear();
		}
	}

	static boolean canLookup(SpotifyPlaybackState state)
	{
		return state != null && state.isItemAvailable() &&
			!state.getTitle().trim().isEmpty() && !state.getArtist().trim().isEmpty();
	}

	static String keyFor(SpotifyPlaybackState state)
	{
		if (!canLookup(state))
		{
			return "";
		}
		return normalize(state.getTitle()) + '\n' + normalize(state.getArtist()) + '\n' +
			normalize(state.getAlbum()) + '\n' + Math.max(0, Math.round(state.getDurationMs() / 1_000f));
	}

	private static String normalize(String value)
	{
		return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
	}

	private void finish(
		String key,
		LyricsState lyrics,
		boolean cacheResult,
		long requestGeneration)
	{
		List<Consumer<LyricsState>> callbacks;
		synchronized (lock)
		{
			if (requestGeneration != generation)
			{
				return;
			}
			callbacks = waiters.remove(key);
			if (cacheResult)
			{
				cache.put(key, lyrics);
			}
		}
		if (callbacks != null)
		{
			for (Consumer<LyricsState> callback : callbacks)
			{
				callback.accept(lyrics);
			}
		}
	}
}

package com.spotifycontroller;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class LyricsParser
{
	private static final int MAXIMUM_LINES = 2_000;
	private static final Pattern TIMESTAMP = Pattern.compile(
		"\\[(\\d{1,3}):(\\d{1,2})(?:[.:](\\d{1,3}))?\\]");

	private LyricsParser()
	{
	}

	static LyricsState parse(String json, Gson gson)
	{
		if (json == null || json.trim().isEmpty())
		{
			return LyricsState.empty();
		}

		try
		{
			JsonObject response = gson.fromJson(json, JsonObject.class);
			if (response == null)
			{
				return LyricsState.empty();
			}

			String syncedLyrics = stringValue(response.get("syncedLyrics"));
			List<LyricsState.Line> syncedLines = parseSynced(syncedLyrics);
			if (!syncedLines.isEmpty())
			{
				return new LyricsState(syncedLines, true);
			}

			String plainLyrics = stringValue(response.get("plainLyrics"));
			List<LyricsState.Line> plainLines = parsePlain(plainLyrics);
			return plainLines.isEmpty()
				? LyricsState.empty()
				: new LyricsState(plainLines, false);
		}
		catch (RuntimeException exception)
		{
			return LyricsState.empty();
		}
	}

	private static List<LyricsState.Line> parseSynced(String lyrics)
	{
		List<LyricsState.Line> lines = new ArrayList<>();
		if (lyrics == null || lyrics.trim().isEmpty())
		{
			return lines;
		}

		for (String rawLine : lyrics.split("\\r?\\n"))
		{
			Matcher matcher = TIMESTAMP.matcher(rawLine);
			List<Long> timestamps = new ArrayList<>();
			int textStart = -1;
			while (matcher.find())
			{
				int seconds = Integer.parseInt(matcher.group(2));
				if (seconds > 59)
				{
					continue;
				}
				long minutes = Long.parseLong(matcher.group(1));
				long fractionMs = fractionMilliseconds(matcher.group(3));
				timestamps.add(((minutes * 60L) + seconds) * 1_000L + fractionMs);
				textStart = matcher.end();
			}

			String text = textStart < 0 ? "" : rawLine.substring(textStart).trim();
			if (text.isEmpty())
			{
				continue;
			}
			for (Long timestamp : timestamps)
			{
				lines.add(new LyricsState.Line(timestamp, text));
				if (lines.size() >= MAXIMUM_LINES)
				{
					break;
				}
			}
			if (lines.size() >= MAXIMUM_LINES)
			{
				break;
			}
		}
		lines.sort(Comparator.comparingLong(LyricsState.Line::getTimestampMs));
		return lines;
	}

	private static List<LyricsState.Line> parsePlain(String lyrics)
	{
		List<LyricsState.Line> lines = new ArrayList<>();
		if (lyrics == null || lyrics.trim().isEmpty())
		{
			return lines;
		}

		for (String rawLine : lyrics.split("\\r?\\n"))
		{
			String text = rawLine.trim();
			if (!text.isEmpty())
			{
				lines.add(new LyricsState.Line(lines.size(), text));
				if (lines.size() >= MAXIMUM_LINES)
				{
					break;
				}
			}
		}
		return lines;
	}

	private static String stringValue(JsonElement value)
	{
		return value == null || value.isJsonNull() ? "" : value.getAsString();
	}

	private static long fractionMilliseconds(String fraction)
	{
		if (fraction == null || fraction.isEmpty())
		{
			return 0L;
		}
		long value = Long.parseLong(fraction);
		if (fraction.length() == 1)
		{
			return value * 100L;
		}
		if (fraction.length() == 2)
		{
			return value * 10L;
		}
		return value;
	}
}

package com.spotifycontroller;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

final class LyricsState
{
	private static final LyricsState EMPTY = new LyricsState(Collections.emptyList(), false);

	private final List<Line> lines;
	private final boolean synced;

	LyricsState(List<Line> lines, boolean synced)
	{
		this.lines = Collections.unmodifiableList(new ArrayList<>(lines));
		this.synced = synced;
	}

	static LyricsState empty()
	{
		return EMPTY;
	}

	boolean isAvailable()
	{
		return !lines.isEmpty();
	}

	boolean isSynced()
	{
		return synced;
	}

	int getLineCount()
	{
		return lines.size();
	}

	Window windowAt(int progressMs, int durationMs)
	{
		return windowAt(progressMs, durationMs, 3);
	}

	Window windowAt(int progressMs, int durationMs, int maximumLines)
	{
		if (lines.isEmpty())
		{
			return Window.empty();
		}

		int currentIndex = synced
			? syncedLineIndex(Math.max(0, progressMs))
			: plainLineIndex(Math.max(0, progressMs), Math.max(0, durationMs));
		int windowSize = Math.min(lines.size(), Math.max(1,
			Math.min(SpotifyControllerConfig.MAX_OVERLAY_LYRIC_LINES, maximumLines)));
		int start = currentIndex - (windowSize / 2);
		start = Math.max(0, Math.min(lines.size() - windowSize, start));
		List<String> visibleLines = new ArrayList<>(windowSize);
		for (int index = start; index < start + windowSize; index++)
		{
			visibleLines.add(lines.get(index).getText());
		}
		return new Window(visibleLines, currentIndex - start);
	}

	private int syncedLineIndex(long progressMs)
	{
		int low = 0;
		int high = lines.size() - 1;
		int result = 0;
		while (low <= high)
		{
			int middle = (low + high) >>> 1;
			if (lines.get(middle).getTimestampMs() <= progressMs)
			{
				result = middle;
				low = middle + 1;
			}
			else
			{
				high = middle - 1;
			}
		}
		return result;
	}

	private int plainLineIndex(int progressMs, int durationMs)
	{
		if (durationMs <= 0)
		{
			return 0;
		}
		long scaledIndex = ((long) progressMs * lines.size()) / durationMs;
		return (int) Math.min(lines.size() - 1L, scaledIndex);
	}

	static final class Line
	{
		private final long timestampMs;
		private final String text;

		Line(long timestampMs, String text)
		{
			this.timestampMs = Math.max(0L, timestampMs);
			this.text = text == null ? "" : text;
		}

		long getTimestampMs()
		{
			return timestampMs;
		}

		String getText()
		{
			return text;
		}
	}

	static final class Window
	{
		private static final Window EMPTY = new Window(Collections.emptyList(), 0);

		private final List<String> lines;
		private final int currentIndex;

		Window(List<String> lines, int currentIndex)
		{
			this.lines = Collections.unmodifiableList(new ArrayList<>(lines));
			this.currentIndex = Math.max(0, Math.min(Math.max(0, lines.size() - 1), currentIndex));
		}

		static Window empty()
		{
			return EMPTY;
		}

		String getPrevious()
		{
			return currentIndex > 0 ? lines.get(currentIndex - 1) : "";
		}

		String getCurrent()
		{
			return lines.isEmpty() ? "" : lines.get(currentIndex);
		}

		String getNext()
		{
			return currentIndex + 1 < lines.size() ? lines.get(currentIndex + 1) : "";
		}

		List<String> getLines()
		{
			return lines;
		}

		int getCurrentIndex()
		{
			return currentIndex;
		}
	}
}

package com.spotifycontroller;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.awt.image.BufferedImage;
import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.net.ServerSocket;
import java.net.Socket;
import java.net.SocketTimeoutException;
import java.net.URI;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.util.ArrayList;
import java.util.Base64;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Consumer;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.LinkBrowser;
import okhttp3.Call;
