	void setQueueState(SpotifyQueueState state)
	{
		queueModel.clear();
		for (SpotifyQueueItem item : state.getItems())
		{
			if (queueModel.size() >= MAXIMUM_QUEUE_ITEMS)
			{
				break;
			}
			queueModel.addElement(item);
		}
		updateQueueSize();
		updateButtons();
	}

