package com.spotifycontroller;

import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.font.TextAttribute;
import java.awt.font.TextLayout;
import java.text.AttributedString;

final class UnicodeText
{
	private static final String[] FALLBACK_FAMILIES =
	{
		"Segoe UI Emoji",
		"Apple Color Emoji",
		"Noto Color Emoji",
		"Noto Emoji",
		"Segoe UI Symbol",
		"Arial Unicode MS",
		Font.DIALOG,
		Font.SANS_SERIF
	};

	private UnicodeText()
	{
	}

	static int stringWidth(Graphics2D graphics, Font preferred, String text)
	{
		if (text == null || text.isEmpty())
		{
			return 0;
		}
		return (int) Math.ceil(layout(graphics, preferred, text).getAdvance());
	}

	static void drawString(Graphics2D graphics, Font preferred, String text, float x, float baselineY)
	{
		if (text == null || text.isEmpty())
		{
			return;
		}
		layout(graphics, preferred, text).draw(graphics, x, baselineY);
	}

	static Font singleFontForText(Font preferred, String text)
	{
		if (text == null || text.isEmpty() || preferred.canDisplayUpTo(text) < 0)
		{
			return preferred;
		}

		for (String family : FALLBACK_FAMILIES)
		{
			Font candidate = new Font(family, preferred.getStyle(), 1).deriveFont(preferred.getSize2D());
			if (candidate.canDisplayUpTo(text) < 0)
			{
				return candidate;
			}
		}
		return new Font(Font.DIALOG, preferred.getStyle(), 1).deriveFont(preferred.getSize2D());
	}

	private static TextLayout layout(Graphics2D graphics, Font preferred, String text)
	{
		AttributedString attributed = new AttributedString(text);
		attributed.addAttribute(TextAttribute.FONT, preferred);
		for (int index = 0; index < text.length();)
		{
			int codePoint = text.codePointAt(index);
			int nextIndex = index + Character.charCount(codePoint);
			if (!preferred.canDisplay(codePoint) || isEmojiCodePoint(codePoint))
			{
				attributed.addAttribute(TextAttribute.FONT,
					fallbackFor(codePoint, preferred), index, nextIndex);
			}
			index = nextIndex;
		}
		return new TextLayout(attributed.getIterator(), graphics.getFontRenderContext());
	}

	private static Font fallbackFor(int codePoint, Font preferred)
	{
		for (String family : FALLBACK_FAMILIES)
		{
			Font candidate = new Font(family, preferred.getStyle(), 1).deriveFont(preferred.getSize2D());
			if (candidate.canDisplay(codePoint))
			{
				return candidate;
			}
		}
		return new Font(Font.DIALOG, preferred.getStyle(), 1).deriveFont(preferred.getSize2D());
	}

	private static boolean isEmojiCodePoint(int codePoint)
	{
		return codePoint >= 0x1F000 ||
			(codePoint >= 0x2600 && codePoint <= 0x27BF) ||
			codePoint == 0x200D ||
			codePoint == 0xFE0F;
	}
}

package com.spotifycontroller;

import com.google.gson.Gson;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class LyricsClientTest
{
	@Test
	public void coalescesAndCachesOneLookupPerTrack() throws Exception
	{
		AtomicInteger requests = new AtomicInteger();
		AtomicReference<HttpUrl> requestedUrl = new AtomicReference<>();
		OkHttpClient httpClient = new OkHttpClient.Builder()
			.addInterceptor(chain ->
			{
				requests.incrementAndGet();
				requestedUrl.set(chain.request().url());
				return new Response.Builder()
					.request(chain.request())
					.protocol(Protocol.HTTP_1_1)
					.code(200)
					.message("OK")
					.body(ResponseBody.create(MediaType.parse("application/json"),
						"{\"syncedLyrics\":\"[00:00.00]Hello\"}"))
					.build();
			})
			.build();
		LyricsClient client = new LyricsClient(httpClient, new Gson());
		SpotifyPlaybackState state = SpotifyPlaybackState.of(
			true, "track", "Song", "Artist", "Album", "Device", "", "", 0, 180_000);

		CountDownLatch callbacks = new CountDownLatch(2);
		client.requestLyrics(state, lyrics -> callbacks.countDown());
		client.requestLyrics(state, lyrics -> callbacks.countDown());
		assertTrue("Lyrics callbacks did not finish", callbacks.await(5, TimeUnit.SECONDS));
		assertEquals(1, requests.get());
		assertEquals("Song", requestedUrl.get().queryParameter("track_name"));
		assertEquals("Artist", requestedUrl.get().queryParameter("artist_name"));
		assertEquals("Album", requestedUrl.get().queryParameter("album_name"));
		assertEquals("180", requestedUrl.get().queryParameter("duration"));

		AtomicInteger cachedCallbacks = new AtomicInteger();
		client.requestLyrics(state, lyrics -> cachedCallbacks.incrementAndGet());
		assertEquals(1, cachedCallbacks.get());
		assertEquals(1, requests.get());
		client.reset();
		httpClient.dispatcher().executorService().shutdownNow();
		httpClient.connectionPool().evictAll();
	}
}

package com.spotifycontroller;

import com.google.gson.Gson;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class LyricsParserTest
{
	private final Gson gson = new Gson();

	@Test
	public void followsSyncedLyricsWithThreeLineWindow()
	{
		String json = "{\"syncedLyrics\":\"[00:01.00]First\\n[00:05.25]Second\\n[00:09.500]Third\\n[00:12.0]Fourth\"}";
		LyricsState lyrics = LyricsParser.parse(json, gson);

		assertTrue(lyrics.isAvailable());
		assertTrue(lyrics.isSynced());
		assertEquals(4, lyrics.getLineCount());
		LyricsState.Window window = lyrics.windowAt(9_750, 15_000);
		assertEquals("Second", window.getPrevious());
		assertEquals("Third", window.getCurrent());
		assertEquals("Fourth", window.getNext());
	}

	@Test
	public void usesPlainLyricsWhenSyncedLyricsAreUnavailable()
	{
		String json = "{\"syncedLyrics\":null,\"plainLyrics\":\"One\\nTwo\\nThree\\nFour\"}";
		LyricsState lyrics = LyricsParser.parse(json, gson);

		assertFalse(lyrics.isSynced());
		LyricsState.Window window = lyrics.windowAt(5_100, 10_000);
		assertEquals("Two", window.getPrevious());
		assertEquals("Three", window.getCurrent());
		assertEquals("Four", window.getNext());
	}

	@Test
	public void ignoresMetadataAndSupportsMultipleTimestamps()
	{
		String json = "{\"syncedLyrics\":\"[ar:Artist]\\n[00:01.0][00:02.00]Echo\"}";
		LyricsState lyrics = LyricsParser.parse(json, gson);

		assertEquals(2, lyrics.getLineCount());
		assertEquals("Echo", lyrics.windowAt(2_100, 3_000).getCurrent());
	}

	@Test
	public void rejectsMalformedOrEmptyResponses()
	{
		assertFalse(LyricsParser.parse("not json", gson).isAvailable());
		assertFalse(LyricsParser.parse("{\"plainLyrics\":\"  \\n\"}", gson).isAvailable());
	}

	@Test
	public void buildsStableLookupKeysWithoutRequiringAnAlbum()
	{
		SpotifyPlaybackState state = SpotifyPlaybackState.of(
			true, "track", " Song ", " ARTIST ", "", "Device", "", "", 0, 181_400);
		assertTrue(LyricsClient.canLookup(state));
		assertEquals("song\nartist\n\n181", LyricsClient.keyFor(state));
	}

	@Test
	public void expandsAndShrinksTheWindowAroundTheCurrentLine()
	{
		String json = "{\"plainLyrics\":\"One\\nTwo\\nThree\\nFour\\nFive\\nSix\\nSeven\"}";
		LyricsState lyrics = LyricsParser.parse(json, gson);

		LyricsState.Window oneLine = lyrics.windowAt(5_000, 10_000, 1);
		assertEquals(1, oneLine.getLines().size());
		assertEquals("Four", oneLine.getCurrent());

		LyricsState.Window sevenLines = lyrics.windowAt(5_000, 10_000, 7);
		assertEquals(7, sevenLines.getLines().size());
		assertEquals(3, sevenLines.getCurrentIndex());
		assertEquals("One", sevenLines.getLines().get(0));
		assertEquals("Seven", sevenLines.getLines().get(6));
	}
}

