				requests.add(path);
				int code = 204;
				byte[] body = new byte[0];
				if (path.endsWith("/currently-playing"))
				{
					code = 200;
					body = playbackJson.getBytes(StandardCharsets.UTF_8);
				}
				else if (path.endsWith("/queue"))
				{
					queueRequested.complete(null);
				}
